 tests=[("Shrug", "Elevate the shoulders against resistance", "Symmetric powerful shrug", "Weak shrug, dropped shoulder, wasted upper trapezius"), ("Head turn", "Turn the chin against your hand", "Strong; sternocleidomastoid contracts visibly on the opposite side to the turn", "Weak turn away from the lesion"), ("Arm abduction", "Abduct the arm above 90 degrees", "Smooth elevation", "Lateral winging of the scapula and difficulty above the horizontal")],
 lesionSigns=[("Isolated trapezius weakness with normal sternocleidomastoid", "posterior triangle (distal to the sternocleidomastoid branch): surgical injury"), ("Both muscles weak", "proximal (jugular foramen or above)"), ("With IX and X palsies", "jugular foramen (Vernet)"), ("Bilateral weakness with tongue and palate involvement", "motor neuron disease or myopathy rather than a nerve lesion")],
